package slowmessage

import (
	"testing"
	"time"
)

type slowFuncForTest struct {
	err error
}

func (sf slowFuncForTest) func() error {
	return sf.err
}

func TestDo(t *testing.T) {
	var sf slowFuncForTest
	sf.err = ErrSlow
	var cb CallbackFunc
	cb = func() {}

	err := Do(time.Second, sf.func(), cb)
	if err != ErrSlow {
		t.Errorf("Expected %v, got %v", ErrSlow, err)
	}
}

func TestDoTimeout(t *testing.T) {
	var sf slowFuncForTest
	sf.err = nil
	var cb CallbackFunc
	cb = func() {}

	err := Do(time.Second, sf.func(), cb)
	if err != nil {
		t.Errorf("Expected nil, got %v", err)
	}
}

